        allocated = (size+3)//4*4
        limit = min(self._gpu.limits["max-buffer-size"], self._gpu.limits["max-storage-buffer-binding-size"])
        if allocated > limit:
            raise ValueError(f"WebGPU buffer exceeds adapter binding/allocation limit {limit}")
